/** Minimal POSIX ustar regular-file writer. Paths are generated by the server, never archive user input. */
export function tarHeader(path: string, bytes: number) {
  if (!/^[a-zA-Z0-9_./-]+$/.test(path) || path.startsWith("/") || path.split("/").includes("..") || path.length > 100)
    throw new Error("Unsafe archive path");
  if (!Number.isSafeInteger(bytes) || bytes < 0 || bytes > 0o77777777777) throw new Error("Archive member too large");
  const header = new Uint8Array(512);
  const text = (offset: number, value: string) => header.set(new TextEncoder().encode(value), offset);
  const octal = (offset: number, length: number, value: number) =>
    text(offset, `${value.toString(8).padStart(length - 1, "0")}\0`);
  text(0, path);
  octal(100, 8, 0o600);
  octal(108, 8, 0);
  octal(116, 8, 0);
  octal(124, 12, bytes);
  octal(136, 12, 0);
  header.fill(32, 148, 156);
  text(156, "0");
  text(257, "ustar\0");
  text(263, "00");
  text(265, "Between");
  const checksum = header.reduce((sum, byte) => sum + byte, 0);
  text(148, `${checksum.toString(8).padStart(6, "0")}\0 `);
  return header;
}

export async function* tarFile(path: string, data: Uint8Array) {
  yield tarHeader(path, data.byteLength);
  yield data;
  const remainder = data.byteLength % 512;
  if (remainder) yield new Uint8Array(512 - remainder);
}
